mapper.select:
SELECT * from (
SELECT subject_id,name subjectName,code subjectCode,`level` from book_subject where code in( SELECT LEFT(bs.code,#{codeNum}) FROM `book_voucher_record` bvr LEFT JOIN book_voucher bv on bv.voucher_id = bvr.voucher_id LEFT JOIN book_subject bs on bvr.subject_id = bs.subject_id where bvr.del_flag = '0' and bv.book_id = #{bookId} and bv.year_period >= #{startPeriod} and bv.year_period <= #{endPeriod} GROUP BY LEFT(bs.code,#{codeNum}) ) and book_id = #{bookId} and `level` = #{index}+1
UNION ALL SELECT bs.subject_id,bs.name subjectName,bs.code subjectCode,bs.`level` from book_subject_period bsp LEFT JOIN book_subject bs on bs.subject_id = bsp.subject_id where bs.book_id = #{bookId} and date_format(bsp.year_period, '%Y %m') >= date_format(DATE_SUB(#{startPeriod}, INTERVAL 1 MONTH),'%Y %m') and YEAR(bsp.year_period) <= YEAR(#{endPeriod}) and bsp.year_period <= #{endPeriod} and bsp.period_end_balance != 0 )a where 1=1
and a.level >= #{startLevel}
and a.level <= #{endLevel}
GROUP BY a.subject_id order BY a.subjectCode
